// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Complex128Array } from '@stdlib/types/array';

/**
* Interface describing `izamax`.
*/
interface Routine {
	/**
	* Finds the index of the first element having the maximum absolute value.
	*
	* @param N - number of indexed elements
	* @param zx - input array
	* @param strideX - stride length for `zx`
	* @returns index value
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
	*
	* var idx = izamax( zx.length, zx, 1 );
	* // returns 1
	*/
	( N: number, zx: Complex128Array, strideX: number ): number;

	/**
	* Finds the index of the first element having the maximum absolute value using alternative indexing semantics.
	*
	* @param N - number of indexed elements
	* @param zx - input array
	* @param strideX - stride length for `zx`
	* @param offsetX - starting index for `zx`
	* @returns index value
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	*
	* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
	*
	* var idx = izamax.ndarray( zx.length, zx, 1, 0 );
	* // returns 1
	*/
	ndarray( N: number, zx: Complex128Array, strideX: number, offsetX: number ): number;
}

/**
* Finds the index of the first element having the maximum absolute value.
*
* @param N - number of indexed elements
* @param zx - input array
* @param strideX - stride length for `zx`
* @returns index value
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var idx = izamax( zx.length, zx, 1 );
* // returns 1
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
*
* var zx = new Complex128Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
*
* var idx = izamax.ndarray( zx.length, zx, 1, 0 );
* // returns 1
*/
declare var izamax: Routine;


// EXPORTS //

export = izamax;
